# Version history: walk a version chain, diff adjacent versions, blame a line.
versions = [{'n': 1, 'date': '2024-01-01', 'author': 'amy', 'msg': 'init', 'text': 'line1'}, {'n': 2, 'date': '2024-01-02', 'author': 'bob', 'msg': 'fix', 'text': 'line1\nline2'}]
def show(v):
    print(f"--- v{v['n']} ({v['date']}) by {v['author']}: {v['msg']}")
chain = sorted(versions, key=lambda v: v["n"])
for v in chain: show(v)
a, b = chain[0], chain[1]
la, lb = a["text"].splitlines(), b["text"].splitlines()
print(f"\ndiff v{a['n']} -> v{b['n']}:")
for line in lb:
    if line not in la: print("  +", line)
for line in la:
    if line not in lb: print("  -", line)

